def test_known_value():
    logits = torch.tensor([[2., 1., 0.], [0., 3., 1.], [1., 0., 5.], [4., 0., 0.]])
    targets = torch.tensor([0, 1, 1, 2])
    assert abs(accuracy(logits, targets) - 0.5) < 1e-9, f"expected 0.5, got {accuracy(logits, targets)}"

def test_returns_python_float():
    out = accuracy(torch.randn(4, 3), torch.tensor([0, 1, 2, 0]))
    assert isinstance(out, float), f"return a Python float, got {type(out).__name__}"

def hidden_all_right_and_all_wrong():
    logits = torch.eye(5)
    assert accuracy(logits, torch.arange(5)) == 1.0
    assert accuracy(logits, (torch.arange(5) + 1) % 5) == 0.0

def hidden_single_sample():
    assert accuracy(torch.tensor([[0.1, 0.9]]), torch.tensor([1])) == 1.0

